def find_max(nums):
    if not nums:
        raise ValueError("find_max() needs at least one number")
    best = nums[0]            # not 0: the list might be all negative
    for x in nums:
        if x > best:
            best = x
    return best

print(find_max([3, -2, 9, 4]))   # 9
print(find_max([-7, -3, -5]))    # -3

def greedy_coins(coins, amount):
    count = 0
    for c in sorted(coins, reverse=True):   # biggest coin first
        count += amount // c
        amount %= c
    return count

def dp_coins(coins, amount):
    best = [0] + [float("inf")] * amount    # best[a] = fewest coins for a
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and best[a - c] + 1 < best[a]:
                best[a] = best[a - c] + 1
    return best[amount]

print(greedy_coins([1, 6, 10], 12), dp_coins([1, 6, 10], 12))           # 3 2
print(greedy_coins([1, 5, 10, 25], 63), dp_coins([1, 5, 10, 25], 63))   # 6 6

from collections import deque

graph = {
    "A": ["B", "C"],
    "B": ["A", "D"],
    "C": ["A", "D", "E"],
    "D": ["B", "C", "F"],
    "E": ["C", "F"],
    "F": ["D", "E"],
}

def bfs_distances(start):
    dist = {start: 0}               # doubles as the visited set
    queue = deque([start])
    while queue:
        node = queue.popleft()      # oldest first: layer by layer
        for nxt in graph[node]:
            if nxt not in dist:     # mark when queued, not when popped
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist

def dfs(node, seen, order):
    seen.add(node)
    order.append(node)
    for nxt in graph[node]:
        if nxt not in seen:
            dfs(nxt, seen, order)   # newest first: go deep
    return order

print(bfs_distances("A"))  # {'A': 0, 'B': 1, 'C': 1, 'D': 2, 'E': 2, 'F': 3}
print(dfs("A", set(), []))  # ['A', 'B', 'D', 'C', 'E', 'F']

